using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace DungeonContract.Editor
{
    public static class DcS2Checks
    {
        private static JObject parameters;
        private static JObject geometry;
        private static readonly List<string> passed=new List<string>();
        private static DcP1World World(string loadout="ranger",bool practice=true)=>new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=geometry,["weapon_stage"]=true,["practice"]=practice,["run_id"]="s2_model",["seed"]=20261012,["members"]=new JArray(new JObject{["player_id"]="1",["slot"]=0,["loadout_id"]=loadout})});
        private static JToken Own(DcP1World world)=>world.Snapshot()["players"][0];
        private static DcP1Input Intent(DcP1World world,ushort aim=0)=>new DcP1Input{WeaponID=world.ActiveWeapon("1"),WeaponRevision=world.WeaponRevision("1"),Aim=aim};
        private static bool Action(DcP1World world,string kind,long at,ushort aim=0){world.AdvanceTime(at);var input=Intent(world,aim);if(kind=="attack_release")input.PressActionID=(string)Own(world)["charge_action_id"];return world.Action("1",kind,input);}
        private static void Tick(DcP1World world,long at){var input=Intent(world);world.Input("1",input);world.Tick(at);}
        private static void Require(bool value,string label){if(!value)throw new InvalidOperationException("S2 "+label);}
        private static void Case(string name,Action check){check();passed.Add(name);}
        private static void Place(DcP1World world,Vector2 player,params Vector2[] targets)
        {
            var state=world.Capture();state["players"][0]["Position"]=new JObject{["x"]=player.x,["y"]=player.y};
            var template=(JObject)(((JArray)state["enemies"]).Count>0?state["enemies"][0]:World().Capture()["enemies"][0]).DeepClone();var enemies=new JArray();
            for(var index=0;index<targets.Length;index++){var enemy=(JObject)template.DeepClone();enemy["ID"]="target_"+index;enemy["Kind"]="guard";enemy["Position"]=new JObject{["x"]=targets[index].x,["y"]=targets[index].y};enemy["Health"]=1000;enemy["Maximum"]=1000;enemy["Warning"]=null;enemy["WarningUntil"]=0;enemy["ChargeUntil"]=0;enemy["HitActions"]=new JArray();enemies.Add(enemy);}
            state["enemies"]=enemies;world.Restore(state);Tick(world,0);
        }
        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/contracts/planned-v4/parameters.json")));
            geometry=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/world-v3-p1.json")));passed.Clear();
            Case("initial ranged two fixed weapons",()=>{var world=World();Tick(world,0);Require(world.ActiveWeapon("1")=="repeating_crossbow"&&!world.MeleeEquipped("1"),"initial");});
            Case("switch cancels reload preserving magazine",()=>{var world=World();Tick(world,0);Action(world,"attack_press",0);Action(world,"reload",200);var magazine=(int)Own(world)["magazine"];Require(Action(world,"switch_weapon",250),"switch");Require((long)Own(world)["reload_remaining_ms"]==0&&(int)Own(world)["magazine"]==magazine&&world.RequiresRelease("1"),"cancel and preserve");});
            Case("held switch does not attack",()=>{var world=World();Tick(world,0);Action(world,"switch_weapon",0);var input=Intent(world);input.Melee=true;world.Input("1",input);world.Tick(33);Require(!(bool)Own(world)["charging"],"held auto attack");});
            Case("short click exactly one ranged shot",()=>{var world=World();Tick(world,0);Require(Action(world,"attack_press",0)&&Action(world,"attack_release",0),"click");Tick(world,33);Require((int)Own(world)["magazine"]==7,"short click lost or duplicated");});
            Case("manual melee light and heavy",()=>{var world=World();Tick(world,0);Action(world,"switch_weapon",0);Tick(world,1);Require(Action(world,"attack_press",2),"light start");Require(Action(world,"attack_release",100),"light release");Require((long)Own(world)["light_attacks"]==1&&(long)Own(world)["heavy_attacks"]==0,"light exclusive");Require(Action(world,"attack_press",500)&&Action(world,"attack_release",1500),"heavy");Require((long)Own(world)["heavy_attacks"]==1,"heavy count");});
            Case("switch cancels charge without release attack",()=>{var world=World();Tick(world,0);Action(world,"switch_weapon",0);Tick(world,1);Action(world,"attack_press",2);Require(Action(world,"switch_weapon",200),"switch back");Require(!(bool)Own(world)["charging"]&&(long)Own(world)["heavy_attacks"]==0,"switch heavy");});
            Case("stale weapon revision rejects",()=>{var world=World();Tick(world,0);var intent=Intent(world);Action(world,"switch_weapon",0);Require(!world.Action("1","attack_press",intent)&&world.LastActionReason=="stale_weapon_revision","stale");});
            Case("ranger pierce two targets",()=>{var world=World();Place(world,new Vector2(3,5),new Vector2(5,5),new Vector2(6.2f,5),new Vector2(7.4f,5));Action(world,"attack_press",0);for(var time=33;time<600;time+=33)Tick(world,time);var enemies=(JArray)world.Snapshot()["enemies"];Require((int)enemies[0]["health"]==988&&(int)enemies[1]["health"]==988&&(int)enemies[2]["health"]==1000,"initial pierce");});
            Case("pierce module adds third",()=>{var world=World();Place(world,new Vector2(3,5),new Vector2(5,5),new Vector2(6.2f,5),new Vector2(7.4f,5));world.InstallForCheck("1","ranger_pierce");Action(world,"attack_press",0);for(var time=33;time<600;time+=33)Tick(world,time);Require(((JArray)world.Snapshot()["enemies"]).All(enemy=>(int)enemy["health"]==988),"module third");});
            Case("rune bolt speed size and no magazine",()=>{var world=World("runesmith");Tick(world,0);Action(world,"attack_press",0);var shot=world.Capture()["projectiles"][0];Require((float)shot["Speed"]==10&&(float)shot["CollisionRadius"]==0.18f&&(int)shot["Damage"]==16&&(int)shot["Bounces"]==1,"rune profile");Require(!Action(world,"reload",100)&&world.LastActionReason=="not_reloadable","no reload");});
            Case("one wall reflection no range reset",()=>{var world=World("runesmith");Place(world,new Vector2(15.5f,5));Action(world,"attack_press",0);for(var time=33;time<200;time+=33)Tick(world,time);var shot=world.Capture()["projectiles"][0];Require((int)shot["Bounces"]==0&&(float)shot["Direction"]["x"]<0&&(float)shot["Remaining"]<9,"reflection");});
            Case("cover damaged then reflected not penetrated",()=>{var world=World("runesmith");Place(world,new Vector2(3,5),new Vector2(6,5));var state=world.Capture();state["covers"]=new JArray(new JObject{["ID"]="box_test",["Room"]=0,["Position"]=new JObject{["x"]=4.5f,["y"]=5},["Health"]=10,["Revision"]=0});world.Restore(state);Tick(world,0);Action(world,"attack_press",0);for(var time=33;time<400;time+=33)Tick(world,time);Require((int)world.Snapshot()["covers"][0]["health"]==0&&(int)world.Snapshot()["enemies"][0]["health"]==1000,"cover behind");});
            Case("volley dash independent of Space",()=>{var world=World();Tick(world,0);Require(Action(world,"ability_primary",0),"volley");Require((long)Own(world)["dodge_remaining_ms"]==0&&(long)Own(world)["dodge_duration_remaining_ms"]==150,"gust CD");Require(!Action(world,"dodge",1)&&(long)Own(world)["dodge_remaining_ms"]==0,"concurrent Space");});
            Case("volley during existing dodge does not refresh",()=>{var world=World();Tick(world,0);Action(world,"dodge",0);Action(world,"ability_primary",100);Require((long)Own(world)["dodge_duration_remaining_ms"]==150&&(long)Own(world)["dodge_remaining_ms"]==2900,"refresh");});
            Case("wind pushes normal and blocks wall attack",()=>{var world=World();Place(world,new Vector2(3,5),new Vector2(3.5f,5));Action(world,"ability_secondary",0);Tick(world,33);Require((float)world.Snapshot()["enemies"][0]["x"]>3.5f,"wind push");Require((string)world.Snapshot()["fields"][0]["kind"]=="wind_bind","wind field");});
            Case("wind erases hostile projectiles",()=>{var world=World();Place(world,new Vector2(3,5));var state=world.Capture();state["projectiles"]=new JArray(new JObject{["ID"]="enemy_bolt",["Action"]="enemy_action",["Owner"]="target",["Room"]=0,["Position"]=new JObject{["x"]=4,["y"]=5},["Direction"]=new JObject{["x"]=-1,["y"]=0},["Remaining"]=10,["Speed"]=6,["Damage"]=12,["Enemy"]=true,["Penetration"]=0,["Hit"]=new JArray(),["CollisionRadius"]=0.1f});world.Restore(state);Tick(world,0);Action(world,"ability_secondary",0);Tick(world,33);Require(((JArray)world.Snapshot()["projectiles"]).Count==0,"clear");});
            Case("feet turret and twin atomic positions",()=>{var world=World("runesmith");Tick(world,0);var position=new Vector2((float)Own(world)["x"],(float)Own(world)["y"]);Action(world,"ability_primary",0);var towers=(JArray)world.Snapshot()["turrets"];Require(towers.Count==1&&Vector2.Distance(position,new Vector2((float)towers[0]["x"],(float)towers[0]["y"]))<0.01f&&(int)towers[0]["damage"]==14,"feet");var twin=World("runesmith");Tick(twin,0);twin.InstallForCheck("1","runesmith_twin");Action(twin,"ability_primary",0);Require(((JArray)twin.Snapshot()["turrets"]).Count==2&&((JArray)twin.Snapshot()["turrets"]).All(tower=>(int)tower["damage"]==9),"twin");});
            Case("shield grant once and follows owner",()=>{var world=World("runesmith");Tick(world,0);Action(world,"ability_secondary",0);Tick(world,33);Require((int)Own(world)["shield"]==20,"grant");Tick(world,3200);Require((int)Own(world)["shield"]==0&&((JArray)world.Snapshot()["fields"]).Count==1,"repeat shield");});
            Case("skills usable while melee equipped",()=>{var world=World("runesmith");Tick(world,0);Action(world,"switch_weapon",0);Require(Action(world,"ability_primary",10)&&Action(world,"ability_secondary",10),"melee skills");});
            Case("rune hammer chain module",()=>{var world=World("runesmith");Place(world,new Vector2(3,5),new Vector2(4,5),new Vector2(5.5f,5));world.InstallForCheck("1","runesmith_chain");Action(world,"switch_weapon",0);Tick(world,1);Action(world,"attack_press",2);Action(world,"attack_release",100);var enemies=(JArray)world.Snapshot()["enemies"];Require((int)enemies[0]["health"]==986&&(int)enemies[1]["health"]==991,"hammer chain");});
            Case("pause preserves new skill lifetimes",()=>{var world=World("runesmith");Tick(world,0);Action(world,"ability_primary",0);world.FreezeInputs();var before=world.Capture().ToString();Require(world.Capture().ToString()==before,"pause capture");world.ResumeInputs();Tick(world,33);Require(((JArray)world.Snapshot()["turrets"]).Count==1,"resume turret");});
            Case("true injury grants 200ms and deduplicates attacks",()=>{var world=World("ranger",false);Place(world,new Vector2(3,5));Hostile(world,"attack_one");Tick(world,33);Require((int)Own(world)["health"]==80,"first hurt");var until=(long)Own(world)["hurt_protection_remaining_ms"];Hostile(world,"attack_two");Tick(world,66);Require((int)Own(world)["health"]==80&&(long)Own(world)["hurt_protection_remaining_ms"]<until,"invalid hit extended");Hostile(world,"attack_one");Tick(world,267);Require((int)Own(world)["health"]==80,"attack repeat");Hostile(world,"attack_three");Tick(world,300);Require((int)Own(world)["health"]==60,"new attack");});
            Case("injury preserves reload and charge",()=>{var world=World("ranger",false);Place(world,new Vector2(3,5));Action(world,"attack_press",0);Action(world,"reload",200);Hostile(world,"reload_hit");Tick(world,233);Require((long)Own(world)["reload_remaining_ms"]>0&&(int)Own(world)["health"]==80,"reload hurt");var melee=World("ranger",false);Place(melee,new Vector2(3,5));Action(melee,"switch_weapon",0);Tick(melee,1);Action(melee,"attack_press",2);Hostile(melee,"charge_hit");Tick(melee,33);Require((bool)Own(melee)["charging"]&&(int)Own(melee)["health"]==80,"charge hurt");});
            Case("wind excludes elite and boss bodies",()=>{var world=World();Place(world,new Vector2(3,5),new Vector2(3.5f,5));var state=world.Capture();state["enemies"][0]["Kind"]="elite";world.Restore(state);Action(world,"ability_secondary",0);Tick(world,33);Require((float)world.Snapshot()["enemies"][0]["x"]==3.5f,"elite pushed");});
            Case("blocked twin deployment keeps cooldown",()=>{var world=World("runesmith");Tick(world,0);world.InstallForCheck("1","runesmith_twin");var state=world.Capture();state["players"][0]["Position"]=new JObject{["x"]=0,["y"]=0};world.Restore(state);Require(!Action(world,"ability_primary",0)&&((JArray)world.Snapshot()["turrets"]).Count==0&&(long)Own(world)["ability_remaining_ms"]==0,"atomic fail");});
            Case("switch preserves each weapon recovery",()=>{var world=World();Tick(world,0);Action(world,"attack_press",0);Action(world,"switch_weapon",1);Tick(world,2);Action(world,"attack_press",3);Action(world,"attack_release",100);Action(world,"switch_weapon",151);Tick(world,152);Action(world,"attack_press",200);Require((int)Own(world)["magazine"]==6,"ranged resource");Require(Action(world,"switch_weapon",301),"second switch");Tick(world,302);Require(!Action(world,"attack_press",303)&&world.LastActionReason=="cooldown","melee recovery bypass");});
            Case("skill buffer becomes final accepted receipt",()=>{var world=World();Tick(world,0);Action(world,"ability_primary",0);Require(Action(world,"ability_primary",3900)&&world.LastActionReason=="buffered","buffer accepted");var id=(string)world.Capture()["players"][0]["BufferedID"];Tick(world,4000);Require(world.Receipt(id)=="accepted"&&(long)Own(world)["ability_remaining_ms"]==4000,"buffer terminal result");});
            Case("switch cancels buffered skill without spending",()=>{var world=World();Tick(world,0);Action(world,"ability_primary",0);Action(world,"ability_primary",3900);var id=(string)world.Capture()["players"][0]["BufferedID"];Action(world,"switch_weapon",3950);Tick(world,4000);Require(world.Receipt(id)=="canceled"&&(long)Own(world)["ability_remaining_ms"]==0,"canceled buffer spent");});
            Case("wall corner reflection terminates within total range",()=>{var world=World("runesmith");Place(world,new Vector2(16.4f,8.4f));Action(world,"attack_press",0,8192);for(var time=33;time<=200;time+=33)Tick(world,time);var shot=world.Capture()["projectiles"][0];Require((int)shot["Bounces"]==0&&(float)shot["Direction"]["x"]<0&&(float)shot["Direction"]["y"]<0,"corner normal");for(var time=231;time<=1200;time+=33)Tick(world,time);Require(((JArray)world.Snapshot()["projectiles"]).Count==0,"range exceeded");});
            Case("rune chain affects one additional enemy only",()=>{var world=World("runesmith");Place(world,new Vector2(3,5),new Vector2(5,5),new Vector2(6,5),new Vector2(7,5));world.InstallForCheck("1","runesmith_chain");Action(world,"attack_press",0);for(var time=33;time<500;time+=33)Tick(world,time);var targets=(JArray)world.Snapshot()["enemies"];Require((int)targets[0]["health"]==984&&(int)targets[1]["health"]==989&&(int)targets[2]["health"]==1000,"recursive chain");});
            Case("injury preserves movement and skill field",()=>{var world=World("runesmith",false);Place(world,new Vector2(3,5));Action(world,"ability_secondary",0);Tick(world,1);Hostile(world,"move_hit");var input=Intent(world);input.Move=Vector2.right;world.Input("1",input);world.Tick(33);Require((float)Own(world)["x"]>3&&(int)Own(world)["shield"]==0&&((JArray)world.Snapshot()["fields"]).Count==1,"hurt interrupted move or skill");});
            Case("pause cancels queued action and advances watermark",()=>{var world=World();Tick(world,0);var input=Intent(world);input.ActionSequence=1;world.QueueAction("1","attack_press",input,"pause_pending_attack");world.FreezeInputs();Require(world.Receipt("pause_pending_attack")=="paused"&&world.WeaponActionSequence("1")==1&&(int)Own(world)["magazine"]==8,"pause dropped ordering");world.ResumeInputs();input=Intent(world);input.ActionSequence=2;Require(world.Action("1","switch_weapon",input),"post pause action gap");});
            File.WriteAllText(DcBootstrap.Argument("-dc-regression-output",(DcBootstrap.DemoEvidenceRoot+"/")+(DcV6Profile.Active?"v6-regression-":"")+"s2-model-checks.json"),new JObject{["kind"]="authoritative_s2_model",["passed"]=passed.Count,["cases"]=new JArray(passed),["human"]=false,["real_udp"]=false,["rewards"]=false}.ToString());Debug.Log("DC S2 checks passed: "+passed.Count);
        }
        private static void Hostile(DcP1World world,string action)
        {
            var state=world.Capture();state["projectiles"]=new JArray(new JObject{["ID"]="hostile_"+action,["Action"]=action,["Owner"]="fixture_enemy",["Room"]=0,["Position"]=new JObject{["x"]=3.2f,["y"]=5},["Direction"]=new JObject{["x"]=-1,["y"]=0},["Remaining"]=10,["Speed"]=6,["Damage"]=20,["Enemy"]=true,["Penetration"]=0,["Hit"]=new JArray(),["CollisionRadius"]=0.1f});world.Restore(state);
        }
    }
}
